-- FlightSchedule is the operational owner of flightNumber/callsign. Repair
-- Flights generated by the retired Route-owned identity path, then propagate
-- the corrected identity to active downstream operational records.
UPDATE "Flight" AS flight
SET "flightNumber" = schedule."flightNumber",
    "callsign" = schedule."callsign",
    "updatedAt" = CURRENT_TIMESTAMP
FROM "FlightSchedule" AS schedule
WHERE flight."scheduleId" = schedule."id"
  AND schedule."flightNumber" IS NOT NULL
  AND schedule."callsign" IS NOT NULL
  AND (flight."flightNumber" IS DISTINCT FROM schedule."flightNumber"
       OR flight."callsign" IS DISTINCT FROM schedule."callsign");

UPDATE "PilotBooking" AS booking
SET "flightNumber" = flight."flightNumber",
    "callsign" = flight."callsign",
    "updatedAt" = CURRENT_TIMESTAMP
FROM "Flight" AS flight
WHERE booking."flightId" = flight."id"
  AND (booking."flightNumber" IS DISTINCT FROM flight."flightNumber"
       OR booking."callsign" IS DISTINCT FROM flight."callsign");

UPDATE "FlightOffer" AS offer
SET "flightNumber" = flight."flightNumber",
    "callsign" = flight."callsign",
    "updatedAt" = CURRENT_TIMESTAMP
FROM "Flight" AS flight
WHERE offer."flightId" = flight."id"
  AND (offer."flightNumber" IS DISTINCT FROM flight."flightNumber"
       OR offer."callsign" IS DISTINCT FROM flight."callsign");
